package com.harish.student_management.entity; import jakarta.persistence.*; import lombok.*; @Entity @Table(name="bus_routes") @Data @Builder @NoArgsConstructor @AllArgsConstructor public class BusRoute { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) Long id; @Column(nullable=false,unique=true,length=100) String name; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="bus_id") Bus bus; @ManyToOne(fetch=FetchType.LAZY) @JoinColumn(name="driver_id") BusDriver driver; @Column(length=20) String status; }
